import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1785319710000}`),a={name:`guide/troubleshooting.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><p>This page collects common problems and how to resolve them.</p><h2 id="application-won-t-start-or-crashes-on-launch" tabindex="-1">Application won&#39;t start or crashes on launch <a class="header-anchor" href="#application-won-t-start-or-crashes-on-launch" aria-label="Permalink to “Application won&#39;t start or crashes on launch”">​</a></h2><p>Symptoms: Sudoku does not open, crashes immediately, or shows an unexpected error.</p><p>Steps to try:</p><ol><li>Ensure your device meets the minimum requirements (iOS/iPadOS 16+, macOS 15+).</li><li>Force-quit and relaunch the app.</li><li>Restart your device.</li><li>Reinstall the app from the App Store.</li><li>If problems persist, open an issue on the project repository with details.</li></ol><h2 id="performance-issues" tabindex="-1">Performance issues <a class="header-anchor" href="#performance-issues" aria-label="Permalink to “Performance issues”">​</a></h2><p>If the game is laggy or slow:</p><ol><li>Close other heavy applications.</li><li>On Mac, check Activity Monitor for high CPU usage.</li><li>On older devices, try an easier difficulty level (Easy or Medium).</li></ol><h2 id="icloud-sync-not-working" tabindex="-1">iCloud sync not working <a class="header-anchor" href="#icloud-sync-not-working" aria-label="Permalink to “iCloud sync not working”">​</a></h2><p>If your progress is not syncing across devices:</p><ol><li>Ensure you are signed into the same Apple ID on all devices.</li><li>Check that iCloud Drive is enabled in System Settings (Mac) or Settings (iOS/iPadOS).</li><li>Verify you have an active internet connection.</li><li>Toggle iCloud off and back on for Sudoku in Settings → [Your Name] → iCloud → Apps Using iCloud.</li><li>Restart all devices and try again.</li></ol><h2 id="game-center-not-connecting" tabindex="-1">Game Center not connecting <a class="header-anchor" href="#game-center-not-connecting" aria-label="Permalink to “Game Center not connecting”">​</a></h2><p>If Game Center achievements or leaderboards are not updating:</p><ol><li>Ensure you are signed into Game Center (Settings → Game Center on iOS; System Settings on Mac).</li><li>Check your internet connection.</li><li>Sign out of Game Center and sign back in.</li></ol><h2 id="view-logs" tabindex="-1">View logs <a class="header-anchor" href="#view-logs" aria-label="Permalink to “View logs”">​</a></h2><p>To troubleshoot crashes, application logs are useful. In sandboxed (App Store) builds on Mac, check:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/Library/Containers/com.w3cub.sudoku/Data/Library/Logs/sudoku/sudoku.log</span></span></code></pre></div><p>On iOS/iPadOS, connect your device to a Mac and use Console.app to view logs, filtering by &quot;Sudoku&quot;.</p><h2 id="resetting-the-app" tabindex="-1">Resetting the app <a class="header-anchor" href="#resetting-the-app" aria-label="Permalink to “Resetting the app”">​</a></h2><p>To reset settings and clear local data (Mac):</p><ol><li>Quit Sudoku</li><li>Remove the container (careful — this deletes all settings, statistics, and game saves):</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><ol start="3"><li>Reopen Sudoku and reconfigure.</li></ol><p>On iPhone/iPad, delete and reinstall the app to reset all data.</p><p><strong>Note</strong>: If you use iCloud sync, resetting on one device may re-download data from iCloud after relaunch. To fully reset across all devices, you may need to reset on each one.</p><h2 id="report-an-issue" tabindex="-1">Report an issue <a class="header-anchor" href="#report-an-issue" aria-label="Permalink to “Report an issue”">​</a></h2><p>When opening an issue, include:</p><ul><li>Device type (iPhone, iPad, or Mac)</li><li>OS version (Settings → General → About)</li><li>Sudoku version (Settings → About)</li><li>Steps to reproduce</li><li>Logs or screenshots if available</li></ul><p>This helps maintainers identify and fix the problem faster.</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};